// Views are addressed as ?view=<id>. The rail shows one entry per section; API and MCP setup are the two tabs of "Connect".
const NAV = [
  ["events", "Events", FiActivity],
  ["dashboards", "Dashboards", FiBarChart2],
  ["devices", "Devices", FiCpu],
  ["catalog", "Catalog", FiBookOpen],
  ["api", "Connect", FiCode],
  ["mcp", "Connect", FiCode],
  ["webhooks", "Webhooks", FiSend],
  ["settings", "Settings", FiSettings],
];
const CONNECT_TABS = [["api", "API"], ["mcp", "MCP"]];
const newId = () => crypto.randomUUID();
const DELIVERY_STATUS = { pending: "Retrying", delivered: "Delivered", failed: "Failed", cancelled: "Cancelled", expired: "Expired" };
const deliveryStatus = (status) => DELIVERY_STATUS[status] ?? status;
// The receiver's last answer: its HTTP status, "No answer" for a timeout or refused
// connection, or a dash before the first attempt.
const responseLabel = (d) => (!d.attemptedAt ? "—" : d.responseStatus ? `HTTP ${d.responseStatus}` : "No answer");
// signing is shown, never sent: the server keeps the secret on edits.
const cleanResource = ({ revision, updatedAt, createdAt, signing, ...record }) => ({
  ...record,
  ...(record.conditions
    ? { conditions: wireConditions(record.conditions) }
    : {}),
});

// The credits glance, loaded when its menu opens (the menu renders its content only while open).
function CreditsPanel({ client, projectId, onAdd }) {
  const [state, setState] = useState({ usage: null, error: null, attempt: 0 });
  useEffect(() => {
    const controller = new AbortController();
    client.usage(projectId, controller.signal)
      .then((usage) => { if (!controller.signal.aborted) setState((current) => ({ ...current, usage, error: null })); })
      .catch((error) => { if (!controller.signal.aborted) setState((current) => ({ ...current, error })); });
    return () => controller.abort();
  }, [client, projectId, state.attempt]);
  return (
    <div className="st-credits-panel">
      {!state.usage && !state.error && <p role="status">Loading credits…</p>}
      {state.usage?.monthly && <CreditsSummary usage={state.usage} onAdd={onAdd} />}
      <Failure error={state.error} retry={() => setState((current) => ({ ...current, error: null, attempt: current.attempt + 1 }))} />
    </div>
  );
}

export default function StreamWorkspace() {
  const auth = useContext(AuthContext);
  const loginLocation = useLocation();
  return (
    <>
      <Helmet>
        <title>Workspace · Plotune Stream</title>
        <meta name="robots" content="noindex,nofollow" />
      </Helmet>
      {!WORKSPACE_ENABLED ? (
        <WorkspaceEntry unavailable />
      ) : auth.isLoading ? (
        <WorkspaceEntry loading />
      ) : !auth.token ? (
        <WorkspaceEntry loginTo={streamWorkspaceLogin(loginLocation.search)} sharedLink={!!loginLocation.search} />
      ) : (
        <Workspace
          key={auth.token}
          token={auth.token}
          user={auth.user}
          logout={auth.logout}
          onUnauthorized={auth.invalidateSession}
        />
      )}
    </>
  );
}

export function Workspace({ token, user, logout, onUnauthorized }) {
  const [params, setParams] = useSearchParams();
  // Projects, their names and the Stream switch come from the workspace API; Stream calls carry a
  // Stream claim for the selected project (renewed through this helper, kept in memory only).
  const claims = useMemo(() => createClaimManager({ requestClaim: workspaceClient.requestClaim }), [token]);
  const workspaces = useWorkspaceList();
  const wantedWorkspace = params.get("workspace") || "";
  const workspaceId = (
    workspaces.items.find((item) => item.id === wantedWorkspace) ||
    workspaces.items.find((item) => item.id === readSelection()?.workspaceId) ||
    workspaces.items[0]
  )?.id || "";
  const workspace = useWorkspaceDetail(workspaceId);
  const client = useMemo(
    () =>
      createStreamClient(token, {
        onUnauthorized: () => onUnauthorized?.(token),
        claims,
        workspaceId,
      }),
    [token, onUnauthorized, claims, workspaceId],
  );
  useEffect(() => {
    if (workspaces.failure?.status === 401 || workspace.failure?.status === 401) onUnauthorized?.(token);
  }, [workspaces.failure, workspace.failure, onUnauthorized, token]);
  const streamProjects = useMemo(
    () => (workspace.workspace?.projects || []).filter((p) => p.services.includes("stream")).map(({ id, name }) => ({ id, name })),
    [workspace.workspace],
  );
  const wantedProject = params.get("project") || "";
  // Only a project of this workspace with Stream switched on can be opened.
  const requestedProject = streamProjects.some((p) => p.id === wantedProject) ? wantedProject : "";
  const projectsLoading = workspaces.status === "loading" || workspaces.status === "idle" || (Boolean(workspaceId) && workspace.status === "loading");
  const metadata = useWorkspaceMetadata(client, requestedProject, ["settings", "webhooks"].includes(params.get("view")) ? params.get("view") : null, streamProjects);
  // A Viewer sees no webhooks, and nothing that changes shared data.
  const navItems = NAV.filter(([id]) => id !== "webhooks" || canSeeWebhooks(metadata.role));
  const view = navItems.some(([id]) => id === params.get("view"))
    ? params.get("view")
    : "events";
  const readOnly = metadata.role === "Viewer";
  const [refreshingShared, setRefreshingShared] = useState(false);
  const refreshShared = async () => {
    setRefreshingShared(true);
    // Check the selected project first; a denied scope must not cancel the fresh project list.
    try { await metadata.reload(); await workspace.reload(); }
    finally { setRefreshingShared(false); }
  };
  const dashboardId = params.get("dashboard");
  const filterId = params.get("filter");
  const location = useCallback(
    (changes, replace = false) => {
      setParams(
        (old) => {
          const next = new URLSearchParams(old);
          Object.entries(changes).forEach(([key, value]) =>
            value ? next.set(key, value) : next.delete(key),
          );
          return next;
        },
        { replace },
      );
    },
    [setParams],
  );
  useEffect(() => {
    if (!requestedProject && !wantedProject && streamProjects.length)
      location({ project: streamProjects[0].id, workspace: workspaceId }, true);
  }, [requestedProject, wantedProject, streamProjects, workspaceId, location]);
  useEffect(() => {
    if (workspace.workspace) rememberSelection({ workspaceId, workspaceName: workspace.workspace.name, projectId: requestedProject || null });
  }, [workspace.workspace, workspaceId, requestedProject]);
  const project = metadata.project;
  const [discoveryState, setDiscoveryState] = useState({});
  const [deliveries, setDeliveries] = useState([]);
  const [deliveryError, setDeliveryError] = useState(null);
  const [deliveryLoading, setDeliveryLoading] = useState(false);
  const [deliveryRefresh, setDeliveryRefresh] = useState(0);
  // C05 saved insights, shown on dashboard tiles.
  const [insights, setInsights] = useState({ projectId: null, items: [] });
  const [insightsRefresh, setInsightsRefresh] = useState(0);
  // Signing dialog: which webhook, and a secret that is shown once after create or rotation.
  const [signing, setSigning] = useState(null);
  const [discoveryRefresh, setDiscoveryRefresh] = useState(0);
  // A shared promo link (?redeem=CODE) opens Add credits once, prefilled.
  const [redeem, setRedeem] = useState(() => {
    const code = params.get("redeem");
    return code ? { code: code.slice(0, 32) } : null;
  });
  useEffect(() => {
    if (!params.has("redeem")) return;
    const next = new URLSearchParams(params);
    next.delete("redeem");
    setParams(next, { replace: true });
  }, [params, setParams]);
  useEffect(() => {
    if (!project?.id || view !== "dashboards") return undefined;
    const controller = new AbortController();
    client.insights(project.id, controller.signal)
      .then((r) => { if (!controller.signal.aborted) setInsights({ projectId: project.id, items: r.items || [] }); })
      // Without the list, insight tiles show as unavailable rather than blocking the dashboard.
      .catch(() => { if (!controller.signal.aborted) setInsights({ projectId: project.id, items: [] }); });
    return () => controller.abort();
  }, [client, project?.id, view, insightsRefresh]);
  // Webhooks use discovered event names so Add webhook offers a choice, not a blank field.
  const needsDiscovery = view === "events" || view === "dashboards" || view === "webhooks" || view === "catalog";
  // A refresh keeps the current project's discovery on screen until the new one arrives.
  useEffect(() => {
    setDiscoveryState((current) => (current.projectId === project?.id ? current : {}));
    if (!project?.id || !needsDiscovery) return undefined;
    const controller = new AbortController();
    client
      .discovery(project.id, controller.signal)
      .then((result) => {
        if (!controller.signal.aborted) setDiscoveryState({ projectId: project.id, data: result });
      })
      .catch((error) => {
        if (!controller.signal.aborted) setDiscoveryState({ projectId: project.id, error });
      });
    return () => controller.abort();
  }, [client, project?.id, needsDiscovery, discoveryRefresh]);
  useEffect(() => {
    setDeliveries([]); setDeliveryError(null); setDeliveryLoading(false);
    if (!project?.id || view !== "webhooks") return undefined;
    const controller = new AbortController();
    const load = () => {
      setDeliveryLoading(true);
      return client
        .deliveries(project.id, controller.signal)
        .then((r) => {
          if (!controller.signal.aborted) {
            setDeliveries(r.items);
            setDeliveryError(null);
          }
        })
        .catch((error) => {
          if (!controller.signal.aborted) setDeliveryError(error);
        }).finally(() => { if (!controller.signal.aborted) setDeliveryLoading(false); });
    };
    const stop = pollWhileVisible(load, 30000);
    return () => {
      controller.abort();
      stop();
    };
  }, [client, project?.id, view, deliveryRefresh]);
  useEffect(() => setSigning(null), [project?.id, view]);
  const retryDiscovery = () => setDiscoveryRefresh((r) => r + 1);
  const save = (kind, record, base) =>
    metadata.mutate(() =>
      client.saveResource(project.id, kind, cleanResource(record), base),
    );
  // The secret is kept as soon as the write succeeds, so a failed refresh afterwards
  // cannot lose it; the refresh failure still shows on the workspace.
  // A response that arrives after the user moved to another project or view is not shown
  // there; the secret can be rotated again from its own project.
  const place = useRef("");
  place.current = `${project?.id}|${view}`;
  const withSecret = async (write, rotated) => {
    let shown = false;
    const origin = place.current;
    try {
      await metadata.mutate(async () => {
        const result = await write();
        if (result?.signingSecret && place.current === origin) {
          shown = true;
          // Keep the written webhook too: a failed refresh leaves it out of the list.
          setSigning({ id: result.id, project: origin, secret: result.signingSecret, rotated, error: null, webhook: resourceData(result) });
        }
        return result;
      });
    } catch (error) {
      if (!shown) throw error;
    }
  };
  const remove = (kind, record, confirmReferenced) =>
    metadata.mutate(() =>
      client.deleteResource(project.id, kind, record, confirmReferenced),
    );
  const safeAction = async (action) => {
    try {
      await action();
    } catch {
      /* The shared mutation notice contains the server error. */
    }
  };
  const dashboard = metadata.dashboards.find((d) => d.id === dashboardId);
  const preview = useCallback(
    async (widget, signal) => {
      const query = {
        name: widget.eventName,
        range: widget.range,
        ...(widget.filterId ? { filterId: widget.filterId } : {}),
      };
      const result = await collectEvents(
        client.pages(requestedProject, query, { signal }),
        { signal },
      );
      const series = buildWidgetSeries(
        result.events,
        { ...widget, filterId: null },
        [],
        result.now,
      );
      return { ...series, events: [], eventCount: series.events.length };
    },
    [client, requestedProject],
  );
  const workspaceName = workspace.workspace?.name || workspaces.items.find((item) => item.id === workspaceId)?.name || "Workspace";
  const projectName = streamProjects.find((p) => p.id === requestedProject)?.name || project?.name || "Select a project";
  const crumbs = [
    {
      label: workspaceName,
      to: workspaceId ? `/workspaces/${encodeURIComponent(workspaceId)}` : "/workspaces",
      menuLabel: "Switch workspace",
      menu: workspaces.items.length > 1 ? (close) => workspaces.items.map((item) => (
        <button key={item.id} type="button" role="menuitem" className={item.id === workspaceId ? "is-current" : undefined}
          onClick={() => { close(); location({ workspace: item.id, project: null, dashboard: null, filter: null }); }}>{item.name}</button>
      )) : undefined,
    },
    {
      label: projectName,
      menuLabel: `Project: ${projectName}`,
      menu: (close) => (
        <>
          {streamProjects.map((p) => (
            <button key={p.id} type="button" role="menuitem" className={p.id === requestedProject ? "is-current" : undefined}
              onClick={() => { close(); location({ project: p.id, workspace: workspaceId, dashboard: null, filter: null }); }}>{p.name}</button>
          ))}
          <Link role="menuitem" className="cs-menu__last" to={workspaceId ? `/workspaces/${encodeURIComponent(workspaceId)}` : "/workspaces"} onClick={close}>Manage in workspace</Link>
        </>
      ),
    },
  ];
  const section = view === "mcp" ? "api" : view;
  const railItems = navItems
    .filter(([id]) => id !== "mcp")
    .map(([id, label, Icon]) => ({
      id, label, icon: Icon, end: id === "settings", active: section === id,
      onClick: () => location({ view: id, dashboard: null, tab: null }),
    }));
  const catalogTab = CATALOG_TABS.some(([id]) => id === params.get("tab")) ? params.get("tab") : "events";
  const tabs = view === "api" || view === "mcp"
    ? CONNECT_TABS.map(([id, label]) => (
      <button key={id} type="button" aria-current={view === id ? "page" : undefined} onClick={() => location({ view: id, dashboard: null })}>{label}</button>
    ))
    : view === "catalog" && project
      ? CATALOG_TABS.map(([id, label]) => (
        <button key={id} type="button" aria-current={catalogTab === id ? "page" : undefined} onClick={() => location({ tab: id === "events" ? null : id })}>{label}</button>
      ))
      : null;
  const action = (
    <>
      <button type="button" className="cs-help st-bar-button" aria-label="Refresh shared settings" title="Refresh shared settings"
        disabled={refreshingShared || metadata.busy || metadata.loading} onClick={refreshShared}>
        <FiRefreshCw aria-hidden="true" className={refreshingShared ? "is-spinning" : undefined} />
      </button>
      {project && (
        <Menu className="st-credits" label="Credits" align="end" button={<><FiCreditCard aria-hidden="true" /><span>Credits</span></>}>
          {(close) => <CreditsPanel client={client} projectId={project.id} onAdd={() => { close(); setRedeem({ code: "" }); }} />}
        </Menu>
      )}
    </>
  );
  return (
    <ReadOnlyContext.Provider value={readOnly}>
    <Console crumbs={crumbs} tabs={tabs} action={action} rail={<Rail items={railItems} label="Workspace navigation" />}>
    <div className="sw-app st-app st-console live-workspace ph-no-capture rr-block">
      <main className="sw-main">
        <div className="sw-content">
          <Failure
            error={metadata.error}
            retry={refreshShared}
          />
          {workspace.failure && workspace.failure.status !== 401 && (
            <div className="live-notice" role="alert">
              <strong>{failureMessage(workspace.failure)}</strong>
              <button className="sw-link" onClick={() => workspace.reload()}>Retry / refresh</button>
            </div>
          )}
          {projectsLoading || metadata.loading ? (
            <p role="status">Loading your workspace…</p>
          ) : !project ? (
            workspaces.items.length === 0 && workspaces.status === "ready" ? (
              <Empty
                title="Create your first workspace"
                description="Projects, teammates and services live in a workspace. Create one, then turn on Stream for a project."
                action={<Link className="sw-button sw-primary" to="/workspaces">Open workspaces</Link>}
              />
            ) : (
              <Empty
                title={wantedProject ? "Project unavailable" : "Turn on Stream for a project"}
                description={
                  wantedProject
                    ? "This project does not have Stream turned on, or you no longer have access. Choose another project, or manage the workspace."
                    : "None of the projects in this workspace has Stream switched on yet. An owner or admin can turn it on in the workspace."
                }
                action={<Link className="sw-button sw-primary" to={workspaceId ? `/workspaces/${encodeURIComponent(workspaceId)}` : "/workspaces"}>Manage in workspace</Link>}
              />
            )
          ) : (
            <React.Fragment key={project.id}>
              {view === "events" && (
                <LiveExplorer
                  client={client}
                  project={project}
                  projectKey={metadata.keys[project.id]}
                  onOpenSetup={() => location({ view: "api", dashboard: null })}
                  discovery={discoveryState.data}
                  discoveryError={discoveryState.error}
                  retryDiscovery={retryDiscovery}
                  filters={metadata.filters}
                  dashboards={metadata.dashboards}
                  activeFilterId={filterId}
                  onSelectFilter={(filter) => location({ filter })}
                  saveFilter={async (filterName, conditions, id, baseline, creationId) => {
                    const base =
                      baseline || metadata.filters.find((f) => f.id === id);
                    const saved = await save(
                      "filters",
                      { id: id || creationId || newId(), name: filterName, conditions },
                      base,
                    );
                    location({ filter: saved.id });
                  }}
                  renameFilter={(id, filterName) => {
                    const base = metadata.filters.find((f) => f.id === id);
                    return save("filters", { ...base, name: filterName }, base);
                  }}
                  deleteFilter={async (id, confirmed) => {
                    const base = metadata.filters.find((f) => f.id === id);
                    try {
                      await remove("filters", base, confirmed);
                    } catch (error) {
                      if (
                        error.code !== "filter_referenced" ||
                        !window.confirm(
                          `${error.message}\nDelete this shared Filter anyway?`,
                        )
                      )
                        throw error;
                      await remove("filters", base, true);
                    }
                    location({ filter: null });
                  }}
                />
              )}
              {view === "dashboards" && (
                <Dashboard
                  key={project.id}
                  projectId={project.id}
                  events={[]}
                  now={Date.now()}
                  discovery={discoveryState.data}
                  loadPreview={preview}
              onRefresh={() => metadata.reload()}
                  dashboards={metadata.dashboards}
                  filters={metadata.filters}
                  selectedDashboardId={dashboardId}
                  onOpen={(id) => location({ dashboard: id })}
                  onBack={() => location({ dashboard: null })}
                  onCreate={(record) => save("dashboards", record)}
                  onRename={(id, dashboardName, description) => {
                    const base = metadata.dashboards.find((d) => d.id === id);
                    return save(
                      "dashboards",
                      { ...base, name: dashboardName, description },
                      base,
                    );
                  }}
                  onDelete={(id) =>
                    remove(
                      "dashboards",
                      metadata.dashboards.find((d) => d.id === id),
                    )
                  }
                  onSaveWidget={(id, widget, base) =>
                    save(
                      "dashboards",
                      {
                        ...base,
                        widgets: base.widgets.some((w) => w.id === widget.id)
                          ? base.widgets.map((w) =>
                              w.id === widget.id ? widget : w,
                            )
                          : [...base.widgets, widget],
                      },
                      base,
                    )
                  }
                  onRemoveWidget={(id, widgetId) => {
                    const base = metadata.dashboards.find((d) => d.id === id);
                    return save(
                      "dashboards",
                      {
                        ...base,
                        widgets: base.widgets.filter((w) => w.id !== widgetId),
                      },
                      base,
                    );
                  }}
                  insights={insights.projectId === project.id ? insights.items : []}
                  onSaveTiles={(id, next, base) => save("dashboards", next, base)}
                  onCreateInsight={async (body) => {
                    const made = await client.createInsight(project.id, body);
                    setInsights((current) => ({ ...current, items: [...current.items, made] }));
                    setInsightsRefresh((r) => r + 1);
                    return made;
                  }}
                  renderInsight={(tile, insight, moves, removeTile) => (
                    <InsightTile client={client} projectId={project.id} tile={tile} insight={insight} moves={moves} onRemove={removeTile} />
                  )}
                  renderGraph={(widget, edit, removeWidget, moves) => (
                    <RemoteGraph
                      moves={moves}
                      key={widget.id}
                      client={client}
                      projectId={project.id}
                      dashboard={dashboard}
                      widget={widget}
                      filters={metadata.filters}
                      onEdit={edit}
                      onRemove={removeWidget}
                    />
                  )}
                />
              )}
              {view === "devices" && <DevicesHealth client={client} project={project} />}
              {view === "catalog" && (
                <Catalog key={project.id} tab={catalogTab} client={client} project={project} role={metadata.role} discovery={discoveryState.data}
                  discoveryError={discoveryState.error} retryDiscovery={retryDiscovery} filters={metadata.filters} />
              )}
              {(view === "api" || view === "mcp") && (
                <ConnectionSetup
                  key={view}
                  client={client}
                  metadata={metadata}
                  mcp={view === "mcp"}
                />
              )}
              {view === "settings" && (
                <ProjectSettings metadata={metadata} workspaceId={workspaceId} />
              )}
              {view === "webhooks" && (
                <>
                  <Webhooks
                    untitled
                    busy={metadata.busy}
                    projectId={project.id}
                    events={[]}
                    discoveredEventNames={discoveryState.data?.eventNames}
                    webhooks={metadata.webhooks}
                    readOnly={!canManageStream(metadata.role)}
                    onSigning={(id) => setSigning({ id, secret: null, rotated: false, error: null, webhook: null })}
                    onCreate={(record) =>
                      withSecret(() => client.saveResource(project.id, "webhooks", cleanResource(record)), false)
                    }
                    onToggle={(id) =>
                      safeAction(() => {
                        const base = metadata.webhooks.find(
                          (w) => w.id === id,
                        );
                        return save(
                          "webhooks",
                          { ...base, enabled: !base.enabled },
                          base,
                        );
                      })
                    }
                    onDelete={(id) => {
                      if (window.confirm("Delete this webhook?"))
                        safeAction(() =>
                          remove(
                            "webhooks",
                            metadata.webhooks.find((w) => w.id === id),
                          ),
                        );
                    }}
                  />
                  {signing && (metadata.webhooks.some((w) => w.id === signing.id) || (signing.webhook && signing.project === place.current)) && (
                    <WebhookSigningDialog
                      webhook={signing.webhook ?? metadata.webhooks.find((w) => w.id === signing.id)}
                      secret={signing.secret}
                      rotated={signing.rotated}
                      canManage={canManageStream(metadata.role)}
                      busy={metadata.busy}
                      error={signing.error}
                      onClose={() => setSigning(null)}
                      onRotate={() =>
                        withSecret(
                          () => client.rotateWebhookSigning(project.id, metadata.webhooks.find((w) => w.id === signing.id)),
                          true,
                        ).catch((error) => {
                          setSigning((current) => current && { ...current, error });
                          // Someone else changed the webhook: load its current revision so a retry can succeed.
                          if (error.code === "revision_conflict") metadata.reload(undefined, false).catch(() => {});
                        })
                      }
                    />
                  )}
                  <Panel title="Delivery status" meta="Last 100 deliveries">
                    <Failure error={deliveryError} retry={() => setDeliveryRefresh((value) => value + 1)} />
                    {deliveryLoading && !deliveries.length && <p className="live-pad" role="status">Loading delivery status…</p>}
                    {deliveries.length ? (
                      <div className="sw-table-wrap" tabIndex={0} role="region" aria-label="Webhook deliveries">
                        <table className="sw-table">
                          <thead>
                            <tr>
                              <th>Webhook</th>
                              <th>Status</th>
                              <th>Attempts</th>
                              <th>Last response</th>
                              <th>Next attempt · UTC</th>
                            </tr>
                          </thead>
                          <tbody>
                            {deliveries.map((d) => (
                              <tr key={d.id}>
                                <td>
                                  {metadata.webhooks.find((w) => w.id === d.webhookId)?.eventName ?? d.webhookId}
                                  <small className="wh-event-id">{d.eventId}</small>
                                </td>
                                <td><span className={`wh-status wh-${d.status}`}>{deliveryStatus(d.status)}</span></td>
                                <td>{d.attempts}</td>
                                <td>{responseLabel(d)}</td>
                                <td>{d.status === "pending" && d.nextAt ? <time dateTime={d.nextAt}>{new Date(d.nextAt).toLocaleString("en-GB", { timeZone: "UTC" })}</time> : "—"}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    ) : !deliveryLoading && !deliveryError && (
                      <p className="live-pad">
                        No deliveries yet. They appear here when a matching event is captured.
                      </p>
                    )}
                  </Panel>
                </>
              )}
            </React.Fragment>
          )}
        </div>
      </main>
      {redeem && (
        <AddCreditsDialog
          client={client}
          initialCode={redeem.code}
          onClose={() => setRedeem(null)}
          onRedeemed={() => {}}
        />
      )}
    </div>
    </Console>
    </ReadOnlyContext.Provider>
  );
}
