import React, { useEffect, useState } from "react";
import { Panel } from "../../StreamWorkspace/WorkspaceUI";
import { mcpExample } from "./examples";
import CaptureGuide from "./CaptureGuide";
import McpSetup from "./McpSetup";
import { FiCopy, FiTerminal } from "react-icons/fi";
import { Failure } from "./LiveExplorer";
import { canManageStream } from "./access";

export default function ConnectionSetup({ client, metadata, mcp = false }) {
  const [suppliedKey, setSuppliedKey] = useState("");
  const [status, setStatus] = useState("");
  const [error, setError] = useState(null);
  const [checking, setChecking] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const [copied, setCopied] = useState(null);
  const raw = metadata.keys[metadata.project.id];
  const key = raw || suppliedKey;
  const snippet = mcpExample(key || "YOUR_CAPTURE_KEY", client.origin);
  const mcpUrl = `${client.origin}/mcp`;
  useEffect(() => {
    if (!copied) return undefined;
    const timer = setTimeout(() => setCopied(null), 2000);
    return () => clearTimeout(timer);
  }, [copied]);
  // Feedback appears on the button that was used; the status line is for keyboard and screen readers.
  const copy = async (text, id = null) => {
    try {
      await navigator.clipboard.writeText(text);
      setError(null);
      setCopied(id);
      setStatus("Copied.");
    } catch {
      setError(new Error("Copy failed. Select the text to copy manually."));
    }
  };
  const keyAccess = (
      <Panel title={mcp ? "Capture key access" : "Project connection"}>
        <div className="st-connection live-project-connection">
          <label>{mcp ? "MCP endpoint" : "Ingestion endpoint"}
            <div className="st-endpoint">
              <code>{client.origin}/{mcp ? "mcp" : "capture"}</code>
              <button className="sw-icon-button" aria-label={mcp ? "Copy MCP endpoint" : "Copy ingestion endpoint"} onClick={() => copy(`${client.origin}/${mcp ? "mcp" : "capture"}`)}><FiCopy /></button>
            </div>
          </label>
          <div className="live-project-key">{raw ? (
            <>
              <p title="It is held only in this browser session and will not be returned again.">
                Copy this capture key now. It is not shown again.
              </p>
              <div className="live-key">
                <input
                  aria-label="New capture key"
                  readOnly
                  type={revealed ? "text" : "password"}
                  value={raw}
                />
                <button
                  className="cs-action"
                  onClick={() => setRevealed(!revealed)}
                >
                  {revealed ? "Hide" : "Reveal"}
                </button>
                <button className="cs-action" onClick={() => copy(raw)}>
                  Copy key
                </button>
              </div>
            </>
          ) : (
            <>
              <p title={metadata.project.hasKey
                ? "Existing keys cannot be recovered."
                : canManageStream(metadata.role)
                  ? "Create one to start sending events; it is shown once."
                  : undefined}>
                {metadata.project.hasKey
                  ? "A capture key is set up for this project."
                  : canManageStream(metadata.role)
                    ? "This project has no capture key yet."
                    : "This project has no capture key yet. An owner or admin can create it."}
              </p>
              {metadata.project.hasKey && (
                <label>
                  Use your existing capture key <span>Optional · held in memory</span>
                  <input
                    type="password"
                    autoComplete="off"
                    value={suppliedKey}
                    onChange={(e) => setSuppliedKey(e.target.value)}
                    placeholder="Paste a capture key to generate examples or check MCP"
                  />
                </label>
              )}
            </>
          )}
          </div>
          {(raw || metadata.project.hasKey) && (
            <p title="This key allows event capture and read-only MCP access.">
              Keep the key in your own secret store.
            </p>
          )}
          {canManageStream(metadata.role) && (
            <div className="live-key-rotation">{metadata.project.hasKey && <p>Replace only to update or revoke client access.</p>}<button
              className="cs-action"
              disabled={metadata.busy}
              onClick={async () => {
                if (
                  metadata.project.hasKey &&
                  !window.confirm(
                    "Rotate this project's capture key? The old key will stop accepting capture and MCP requests. Update every client that uses it.",
                  )
                )
                  return;
                try {
                  await metadata.rotate();
                  setSuppliedKey("");
                  setStatus(metadata.project.hasKey ? "New key created. Update your clients." : "Capture key created. Copy it now.");
                } catch (cause) {
                  setError(cause);
                }
              }}
            >
              {metadata.project.hasKey ? "Rotate capture key" : "Create capture key"}
            </button></div>
          )}
        </div>
      </Panel>
  );
  if (!mcp) return (
    <>
      {keyAccess}
      <Panel title="Send an event over HTTP">
        <CaptureGuide titled apiKey={key} origin={client.origin} />
      </Panel>
      <Failure error={error} />
      {status && <p role="status">{status}</p>}
    </>
  );
  return (
    <>
      <Panel title="Connect your AI client">
        <McpSetup url={mcpUrl} projectName={metadata.project.name} copy={copy} copied={copied} />
      </Panel>
      <Panel title="Ask your AI agent" meta="Read-only. It does not control hardware.">
        <div className="st-mcp-example" title="Reads events, dashboards and health for this project.">
          <span>Try asking</span><q>Which devices stopped sending in the last hour, and why?</q>
        </div>
      </Panel>
      <details className="mcp-key-alternative">
        <summary>Use a capture key instead</summary>
        <p className="st-muted" title="A capture key reads event history only; dashboards, analysis and health need sign-in.">For clients without sign-in support.</p>
        {keyAccess}
        <Panel title="Client configuration">
        <div className="st-connection live-mcp-config">
          <p title="Configuration format varies by MCP client.">Use the endpoint and key in your client's MCP settings.</p>
          <div className="sw-code-head">
            <span>Client configuration</span>
            <button className="sw-link" onClick={() => copy(snippet)}>Copy example</button>
          </div>
          <pre className="sw-code" tabIndex={0} aria-label="MCP configuration">{snippet}</pre>
          <button
              className="cs-action"
              disabled={!key || checking}
              onClick={async () => {
                setChecking(true);
                setError(null);
                setStatus("");
                try {
                  const response = await client.mcp(key);
                  if (response.error || !response.result?.protocolVersion)
                    throw new Error(
                      response.error?.message ||
                        "MCP did not initialize successfully.",
                    );
                  setStatus(
                    `MCP connected · protocol ${response.result.protocolVersion}`,
                  );
                } catch (cause) {
                  setError(cause);
                } finally {
                  setChecking(false);
                }
              }}
            >
              {checking ? "Checking…" : "Check MCP connection"}
            </button>
        </div>
        </Panel>
      </details>
      <Failure error={error} />
      {status && <p role="status">{status}</p>}
    </>
  );
}
